import Foundation
import PLContent
import PLCore
import PLFaith

/// `scripture-library.json`: which works can be read, their books and chapters, and every
/// bundled edition with its provenance. Generated by `scripts/import_scripture.py`.
public struct ScriptureManifest: Decodable, Sendable {
    public var version: Int
    public var works: [ScriptureWork]
    public var editions: [ScriptureEdition]

    public func work(_ id: SourceWorkID) -> ScriptureWork? { works.first { $0.id == id } }
    public func work(for faith: FaithID) -> ScriptureWork? { works.first { $0.faith == faith } }
    public func edition(_ id: EditionID) -> ScriptureEdition? { editions.first { $0.id == id } }
}

/// A readable scripture (the Bible, the Quran, the Bhagavad Gita).
public struct ScriptureWork: Decodable, Identifiable, Hashable, Sendable {
    public var id: SourceWorkID
    public var faith: FaithID
    public var title: LocalizedText
    /// The everyday name ("Bible", "Quran", "Gita") — used for the tab.
    public var shortTitle: LocalizedText
    public var translation: EditionID
    /// Original-language editions. The Bible has two (Hebrew OT, Greek NT); each covers its books.
    public var originals: [EditionID]
    public var transliteration: EditionID?
    /// Whether original and translation share verse numbering, so they can be shown verse by verse.
    public var parallel: Bool
    public var books: [ScriptureBook]

    public func book(_ id: String) -> ScriptureBook? { books.first { $0.id == id } }

    /// The Quran and the Gita are one book; the library then lists chapters directly.
    public var isSingleBook: Bool { books.count == 1 }
}

public struct ScriptureBook: Decodable, Identifiable, Hashable, Sendable {
    public enum Group: String, Decodable, Sendable {
        case oldTestament
        case newTestament
    }

    public var id: String
    public var title: LocalizedText
    /// Singular form used in references ("Psalm 46:10"), when it differs from the title.
    public var referenceTitle: LocalizedText?
    public var group: Group?
    public var chapterCount: Int
    /// Chapter names, for works that name their chapters (surahs, Gita chapters).
    public var chapters: [ScriptureChapterInfo]?

    public func chapterInfo(_ chapter: Int) -> ScriptureChapterInfo? {
        guard let chapters, chapters.indices.contains(chapter - 1) else { return nil }
        return chapters[chapter - 1]
    }
}

public struct ScriptureChapterInfo: Decodable, Hashable, Sendable {
    public var title: LocalizedText
    public var originalTitle: String?
    public var transliteratedTitle: String?
    /// Extra fact (e.g. `meccan` / `medinan` for surahs).
    public var detail: String?
}

/// A bundled edition and its provenance.
public struct ScriptureEdition: Decodable, Identifiable, Hashable, Sendable {
    public enum Role: String, Decodable, Sendable {
        case translation
        case original
        case transliteration
    }

    public enum Direction: String, Decodable, Sendable {
        case ltr
        case rtl
    }

    /// `verse`: numbered verses. `passage`: a translation that follows chapters but not
    /// verses (Arnold's poem), so it is never shown verse by verse.
    public enum Unit: String, Decodable, Sendable {
        case verse
        case passage
    }

    public struct Source: Decodable, Hashable, Sendable {
        public var url: URL
        public var sha256: String
        public var retrieved: String
    }

    public var id: EditionID
    public var work: SourceWorkID
    public var role: Role
    public var title: LocalizedText
    public var shortTitle: String
    /// BCP-47 language (`en`, `hbo`, `grc`, `ar`, `sa`).
    public var language: String
    public var script: String
    public var direction: Direction
    /// Numbering scheme. Two editions can be shown verse by verse only when these match.
    public var versification: String
    public var unit: Unit
    public var books: [String]
    public var chapterCounts: [String: Int]
    public var attribution: String
    public var attributionURL: URL?
    /// A licence notice that must accompany the text (Tanzil's copyright block).
    public var notice: String?
    /// What the importer changed (formatting only, or nothing).
    public var modifications: String
    public var source: Source
    public var review: ReviewInfo

    public func covers(book: String) -> Bool { chapterCounts[book] != nil }
    public func chapterCount(book: String) -> Int { chapterCounts[book] ?? 0 }
}

/// An edition's text: books → chapters → verses (or passages).
struct EditionText: Decodable, Sendable {
    struct Book: Decodable, Sendable {
        var id: String
        var chapters: [[String]]
        /// "chapter:unit" → speaker ("arjuna uvāca", "Krishna").
        var speakers: [String: String]?
    }

    var id: EditionID
    var books: [Book]
}

/// One verse or passage, ready to display.
public struct ScriptureUnit: Hashable, Sendable, Identifiable {
    public var number: Int
    public var text: String
    /// Who speaks from here (the Gita's narrators and speakers).
    public var speaker: String?

    public var id: Int { number }

    public init(number: Int, text: String, speaker: String? = nil) {
        self.number = number
        self.text = text
        self.speaker = speaker
    }
}

/// A chapter of one edition. Empty verse slots (verses an edition omits) are skipped.
public struct ScriptureChapter: Hashable, Sendable {
    public var edition: EditionID
    public var book: String
    public var chapter: Int
    public var units: [ScriptureUnit]

    public func unit(_ number: Int) -> ScriptureUnit? { units.first { $0.number == number } }
}

/// A position in a work.
public struct ScriptureLocation: Codable, Hashable, Sendable {
    public var work: SourceWorkID
    public var book: String
    public var chapter: Int

    public init(work: SourceWorkID, book: String, chapter: Int) {
        self.work = work
        self.book = book
        self.chapter = chapter
    }
}

/// A verse range within one chapter, e.g. Psalm 46:10 or Quran 94:5–6.
public struct PassageReference: Codable, Hashable, Sendable {
    public var book: String
    public var chapter: Int
    public var firstVerse: Int
    public var lastVerse: Int

    public init(book: String, chapter: Int, firstVerse: Int, lastVerse: Int? = nil) {
        self.book = book
        self.chapter = chapter
        self.firstVerse = firstVerse
        self.lastVerse = lastVerse ?? firstVerse
    }

    public var verses: ClosedRange<Int> { firstVerse...max(firstVerse, lastVerse) }
}
